@php($c='min-h-11 w-full rounded-xl border px-3.5 py-2.5')<x-admin.layout :title="$category->exists?'Edit blog category':'Add blog category'" eyebrow="Content"><form method="POST" action="{{ $category->exists?route('admin.blog-categories.update',$category):route('admin.blog-categories.store') }}" class="mx-auto max-w-2xl space-y-5 rounded-2xl bg-white p-5 ring-1 ring-slate-200">@csrf @if($category->exists)@method('PUT')@endif<input name="name" value="{{ old('name',$category->name) }}" placeholder="Name" class="{{ $c }}"><input name="slug" value="{{ old('slug',$category->slug) }}" placeholder="Slug" class="{{ $c }}"><textarea name="description" placeholder="Description" class="{{ $c }}">{{ old('description',$category->description) }}</textarea><div class="grid gap-4 sm:grid-cols-2"><select name="status" class="{{ $c }}"><option value="draft">Draft</option><option value="published" @selected(old('status',$category->status?->value)==='published')>Published</option></select><input name="sort_order" type="number" min="0" value="{{ old('sort_order',$category->sort_order??0) }}" class="{{ $c }}"></div><button class="min-h-12 w-full rounded-xl bg-[#082f57] text-white">Save category</button></form></x-admin.layout>
